<template><section class="searchbox"><h1 style="font-size:38px">今天想了解什么？</h1><p class="muted">从团队知识库中获得有据可查的答案</p><el-input v-model="query" size="large" placeholder="搜索文档、项目或问题" @keyup.enter="search"><template #append><el-button type="primary" @click="search">搜索</el-button></template></el-input><div style="margin-top:18px"><el-button text @click="$router.push('/chat')">开始问答对话 →</el-button></div></section></template>
